const fs=require('fs'),crypto=require('crypto'),assert=require('assert/strict');const before=JSON.parse(fs.readFileSync('releases/v280/manifest.json')),after=JSON.parse(fs.readFileSync('releases/v281/manifest.json'));const allowed=['app.html','provenance.json','lts-v226-card-composition.js'];assert.deepEqual(Object.keys(before.files).sort(),Object.keys(after.files).sort());for(const[n,h]of Object.entries(before.files))if(!allowed.includes(n))assert.equal(after.files[n],h,n);for(const[n,h]of Object.entries(after.files))assert.equal(crypto.createHash('sha256').update(fs.readFileSync('releases/v281/'+n)).digest('hex'),h,n);for(const[n,h]of Object.entries(after.protected))assert.equal(crypto.createHash('sha256').update(fs.readFileSync(n)).digest('hex'),h,n);assert.equal(after.files['lts-v226-card-composition.js'],'e76f4d63e81d435c16790fd0a9063bd895d96e042955f9bc3fe4ec5cc80bbf49');assert(fs.readFileSync('releases/v280/index.html').equals(fs.readFileSync('releases/v281/index.html')));console.log('Only reviewed V226 presentation plus release metadata changed; all protected assets intact');